 rows=p.evaluate('''()=>{const A=SVG_FIGHTER,R=INK.Runtime,rows=[],world=f=>({x:f.x,y:665+f.y,scale:f.renderScale||f.ch.scale||1,facing:f.dir});for(const id of INK.Schema.CHARACTERS)for(const back of [false,true]){const a=throwSample(id,back,14),f=A.fighters[0],d=A.fighters[1];if(!a){rows.push({id,back,grab:false});continue;}const p=A.visualPose(f),q=A.visualPose(d),r=R.visualRig(f,p),s=INK.Rig.sockets(q,R.visualRig(d,q)),hands=INK.Rig.sockets(p,r),errors=[];for(const [side,other]of [['frontArm','rearArm'],['rearArm','frontArm']]){const anchor=INK.Rig.world(q,INK.vec.mix(s[other][0],s.chest,.3),world(d)),actual=INK.Rig.world(p,hands[side][2],world(f));const chosen=INK.ThrowBody.inspect(p)?.[side==='frontArm'?'front':'rear'];errors.push({collar:Math.hypot(anchor[0]-actual[0],anchor[1]-actual[1]),chosen:chosen?Math.hypot(chosen.anchor[0]-actual[0],chosen.anchor[1]-actual[1]):null,diagnostic:chosen});}rows.push({id,back,grab:true,t:a.t,errors,frontFoot:p.fa,rearFoot:p.ra});}for(const id of ['cammy','iori','juri']){throwSample(id,false,4);let previous=null,steps=[];for(let t=4;t<=23;t++){const f=A.fighters[0],p=A.visualPose(f),r=R.visualRig(f,p),hands=INK.Rig.sockets(p,r),diag=INK.ThrowBody.inspect(p);const raw=R.visual(f,A.pose(f),null,true),rawRig=R.visualRig(f,raw),rawSockets=INK.Rig.sockets(raw,rawRig),target=A.fighters[1],tp=A.visualPose(target),ts=INK.Rig.sockets(tp,R.visualRig(target,tp)),tw=world(target),toWorld=x=>INK.Rig.world(tp,x,tw),row={t,diagnostic:diag,bodyYaw:INK.Turn.angle(p,'body'),armYaw:[p.frontArmYaw,p.rearArmYaw],hands:{},rawHands:{},anchors:{},segments:{},regions:{}};for(const [side,name]of [['front','frontArm'],['rear','rearArm']]){row.hands[side]=INK.Rig.world(p,hands[name][2],world(f));row.rawHands[side]=INK.Rig.world(raw,rawSockets[name][2],world(f));row.anchors[side]=diag[side].anchor;row.segments[side]=diag[side].segment;const other=side==='front'?'rearArm':'frontArm';row.regions[side]=[[toWorld(ts[other][0]),toWorld(ts[other][1])],[toWorld(ts[other][0]),toWorld(ts.chest)],[toWorld(ts.chest),toWorld(INK.vec.mix(ts.chest,ts.pelvis,.55))]];}if(previous)for(const side of ['front','rear']){row[side+'HandStep']=Math.hypot(...row.hands[side].map((v,i)=>v-previous.hands[side][i]));const index=diag[side].segment,at=diag[side].t;if(index>=0){const seg=previous.regions[side][index],prevAt=seg[0].map((v,i)=>v+(seg[1][i]-v)*at);row[side+'Slide']=Math.hypot(...prevAt.map((v,i)=>v-previous.anchors[side][i]));row[side+'BodyStep']=Math.hypot(...row.anchors[side].map((v,i)=>v-prevAt[i]));}row[side+'RawStep']=Math.hypot(...row.rawHands[side].map((v,i)=>v-previous.rawHands[side][i]));row[side+'AnchorStep']=Math.hypot(...row.anchors[side].map((v,i)=>v-previous.anchors[side][i]));}steps.push(row);previous=row;A.step();}rows.push({id,sequence:steps,grab:true});}return rows;}''')
